fn is_greater(arr: &Vec<i32>, number: i32) -> bool {
    // For each element in the array, check if `number` is greater.
    // If we find any element that is >= number, we can immediately return false.
    for &elem in arr.iter() {
        if number <= elem {
            return false;
        }
    }
    // If we never found an element >= number (or the array is empty),
    // then `number` is strictly greater than every element.
    true
}

